import Redis from 'ioredis';

export interface OrderCreatedEvent {
  orderId: string;
  userId: string;
  totalAmount: number;
  items: { sku: string; quantity: number }[];
  timestamp: string;
}

export class EventProducer {
  private redis: Redis;
  private streamName: string;

  constructor(redisUrl: string, streamName: string = 'order-events') {
    this.redis = new Redis(redisUrl);
    this.streamName = streamName;
  }

  public async publishOrderCreated(event: OrderCreatedEvent): Promise<string> {
