      // XADD stream-name * field1 value1 field2 value2 ...
      const messageId = await this.redis.xadd(
        this.streamName,
        '*',
        'event_type',
        'ORDER_CREATED',
        'payload',
        JSON.stringify(event)
      );

      console.log(`[Producer] Event published successfully: ${messageId}`);
      return messageId;
    } catch (error) {
      console.error('[Producer] Failed to publish event:', error);
      throw error;
    }
  }
}


