## Implementing the Resilient Consumer Worker

Consuming events reliably requires handling consumer groups, acknowledging processed messages, and recovering dead-letter or stalled messages using the Pending Entries List (PEL).

typescript
import Redis from 'ioredis';

export class EventConsumer {
  private redis: Redis;
  private streamName: string;
  private groupName: string;
  private consumerName: string;
  private isRunning: boolean = false;

  constructor(
    redisUrl: string,
    streamName: string,
    groupName: string,
    consumerName: string
  ) {
    this.redis = new Redis(redisUrl);
    this.streamName = streamName;
    this.groupName = groupName;
    this.consumerName = consumerName;
  }

  private async ensureConsumerGroup(): Promise<void> {
    try {
      // MKSTREAM automatically creates the stream if it doesn't exist
      await this.redis.xgroup(
        'CREATE',
        this.streamName,
        this.groupName,
        '$',
        'MKSTREAM'
      );
    } catch (error: any) {
      if (!error.message.includes('BUSYGROUP')) {
        throw error;
      }
      // Group already exists, safe to ignore
    }
  }

  public async start(onMessage: (payload: any, messageId: string) => Promise<void>): Promise<void> {
    await this.ensureConsumerGroup();
    this.isRunning = true;

    console.log(`[Consumer] ${this.consumerName} started listening on group ${this.groupName}...`);

    while (this.isRunning) {
      try {
        // Read new messages destined for this consumer group
        // XREADGROUP GROUP group-name consumer-name BLOCK 5000 STREAMS stream-name >
        const response = await this.redis.xreadgroup(
          'GROUP',
          this.groupName,
          this.consumerName,
          'BLOCK',
          5000,
          'COUNT',
          10,
          'STREAMS',
          this.streamName,
          '>'
        );

        if (!response) continue;

        for (const [, messages] of response) {
          for (const [messageId, fields] of messages) {
            await this.processMessage(messageId, fields, onMessage);
          }
        }
      } catch (error) {
        console.error('[Consumer Error]', error);
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }
    }
  }

  private async processMessage(
    messageId: string,
    fields: string[],
    onMessage: (payload: any, messageId: string) => Promise<void>
  ): Promise<void> {
    const payloadIndex = fields.indexOf('payload');
    if (payloadIndex === -1) return;

    const rawPayload = fields[payloadIndex];

    try {
      const parsedPayload = JSON.parse(rawPayload);
      await onMessage(parsedPayload, messageId);

      // Acknowledge message processing completion
      await this.redis.xack(this.streamName, this.groupName, messageId);
      console.log(`[Consumer] Acknowledged message ID: ${messageId}`);
    } catch (err) {
      console.error(`[Consumer] Failed processing message ${messageId}:`, err);
      // Implement Dead Letter Queue (DLQ) or retry backoff strategy here
    }
  }

  public stop(): void {
    this.isRunning = false;
    this.redis.quit();
  }
}


---

## Handling Failures & Pending Entries (PEL Recovery)

When a microservice crashes mid-processing, messages remain in the Pending Entries List (PEL). To prevent message loss, implement a background recovery loop using `XPENDING` and `XCLAIM` to reassign stalled messages to active workers.

typescript
public async recoverStalledMessages(minIdleTimeMs: number = 60000): Promise<void> {
  try {
    // Inspect pending messages
    const pending = await this.redis.xpending(
      this.streamName,
      this.groupName,
      '-',
      '+',
      10
    );

    for (const message of pending) {
      const [messageId, consumer, idleTime] = message;

      if (idleTime > minIdleTimeMs) {
        // Claim ownership of the stalled message
        const claimed = await this.redis.xclaim(
          this.streamName,
          this.groupName,
          this.consumerName,
          minIdleTimeMs,
          messageId
        );

        if (claimed && claimed.length > 0) {
          console.log(`[Recovery] Claimed stalled message ${messageId} from dead consumer ${consumer}`);
        }
      }
    }
  } catch (error) {
    console.error('[Recovery Error]', error);
  }
}


