## 3. TypeScript Ingestion Pipeline

Let's write a robust TypeScript module using the `@google/genai` SDK and the Supabase JavaScript client to chunk and ingest source documents.

typescript
import { GoogleGenAI } from '@google/genai';
import { createClient } from '@supabase/supabase-js';

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const supabase = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);

interface IngestInput {
    documentId: string;
    content: string;
    metadata: Record<string, any>;
}

export async function ingestDocument({ documentId, content, metadata }: IngestInput): Promise<void> {
    // 1. Chunk text (simplified 500-char window with 50-char overlap)
    const chunks = chunkText(content, 500, 50);

    for (const chunk of chunks) {
        // 2. Generate embedding using Gemini
        const embeddingResponse = await ai.models.embedContent({
            model: 'text-embedding-004',
            content: chunk,
        });

        const vector = embeddingResponse.embedding?.values;
        if (!vector) throw new Error('Failed to generate vector embedding.');

        // 3. Insert into Supabase
        const { error } = await supabase.from('knowledge_chunks').insert({
            document_id: documentId,
            content: chunk,
            metadata,
            embedding: vector,
        });

        if (error) throw new Error(`Supabase insert failed: ${error.message}`);
    }
}

function chunkText(text: string, size: number, overlap: number): string[] {
    const chunks: string[] = [];
    for (let i = 0; i < text.length; i += size - overlap) {
        chunks.push(text.slice(i, i + size));
    }
    return chunks;
}


