## 4. Implementing Reciprocal Rank Fusion (RRF) in PostgreSQL

To combine keyword (`ts_rank`) and semantic (`vector_cosine_ops`) results cleanly without worrying about disparate score scales, we implement Reciprocal Rank Fusion (RRF) directly inside a PostgreSQL Function (RPC).

sql
create or replace function hybrid_search(
    query_text text,
    query_embedding vector(768),
    match_count int,
    full_text_weight float default 1.0,
    semantic_weight float default 1.0
)
returns table (
    id uuid,
    content text,
    metadata jsonb,
    combined_score float
)
language sql
as $$
with semantic_matches as (
    select 
        id,
        content,
        metadata,
        row_number() over (order by embedding <=> query_embedding) as rank
    from knowledge_chunks
    order by embedding <=> query_embedding
    limit match_count * 2
),
keyword_matches as (
    select 
        id,
        content,
        metadata,
        row_number() over (order by ts_rank(fts, plainto_tsquery('english', query_text)) desc) as rank
    from knowledge_chunks
    where fts @@ plainto_tsquery('english', query_text)
    order by ts_rank(fts, plainto_tsquery('english', query_text)) desc
    limit match_count * 2
)
select 
    coalesce(s.id, k.id) as id,
    coalesce(s.content, k.content) as content,
    coalesce(s.metadata, k.metadata) as metadata,
    (
        coalesce(1.0 / (60 + s.rank), 0.0) * semantic_weight +
        coalesce(1.0 / (60 + k.rank), 0.0) * full_text_weight
    ) as combined_score
from semantic_matches s
full outer join keyword_matches k on s.id = k.id
order by combined_score desc
limit match_count;
$$


