typescript
import { createClient } from 'redis';
import { WebSocket, WebSocketServer } from 'ws';
import { IncomingMessage } from 'http';
import * as dotenv from 'dotenv';

dotenv.config();

const PORT = process.env.PORT ? parseInt(process.env.PORT) : 8080;

// Initialize Redis Clients for Pub and Sub
const pubClient = createClient({ url: process.env.REDIS_URL || 'redis://localhost:6379' });
const subClient = pubClient.duplicate();

interface AuthenticatedWebSocket extends WebSocket {
  userId?: string;
  isAlive?: boolean;
}

const wss = new WebSocketServer({ noServer: true });
const rooms = new Map<string, Set<AuthenticatedWebSocket>>();

function heartbeat(this: AuthenticatedWebSocket) {
  this.isAlive = true;
}

// Broadcast message to local clients in a room
function broadcastToRoom(room: string, message: string) {
  const clients = rooms.get(room);
  if (clients) {
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    }
  }
}

async function bootstrap() {
  await pubClient.connect();
  await subClient.connect();

  // Subscribe to Redis global dashboard channel
  await subClient.subscribe('dashboard-events', (message) => {
    const parsed = JSON.parse(message);
    broadcastToRoom(parsed.room, JSON.stringify(parsed.payload));
  });

  const server = require('http').createServer();

  server.on('upgrade', (request: IncomingMessage, socket: any, head: any) => {
    // Perform auth token validation from query params or headers here
    wss.handleUpgrade(request, socket, head, (ws) => {
      wss.emit('connection', ws, request);
    });
  });

  wss.on('connection', (ws: AuthenticatedWebSocket, req: IncomingMessage) => {
    ws.isAlive = true;
    ws.on('pong', heartbeat);

    // Parse URL for room subscriptions (e.g., /?room=analytics-us-east)
    const urlParams = new URLSearchParams(req.url?.split('?')[1]);
    const room = urlParams.get('room') || 'default';

    if (!rooms.has(room)) {
      rooms.set(room, new Set());
    }
    rooms.get(room)!.add(ws);

    ws.on('message', async (data: string) => {
      try {
        const packet = JSON.parse(data);
        // Publish event to Redis cluster backplane
        await pubClient.publish('dashboard-events', JSON.stringify({
          room,
          payload: packet
        }));
      } catch (err) {
        console.error('Invalid JSON frame received', err);
      }
    });

    ws.on('close', () => {
      rooms.get(room)?.delete(ws);
      if (rooms.get(room)?.size === 0) {
        rooms.delete(room);
      }
    });
  });

  // Heartbeat interval to clean up dead connections
  const interval = setInterval(() => {
    wss.clients.forEach((ws: AuthenticatedWebSocket) => {
      if (ws.isAlive === false) return ws.terminate();
      ws.isAlive = false;
      ws.ping();
    });
  }, 30000);

  wss.on('close', () => clearInterval(interval));

  server.listen(PORT, () => {
    console.log(`WebSocket server running on port ${PORT}`);
  });
}

bootstrap().catch(console.error);


